NUMTYPES = {"ZZ32","ZZ64","NN32","NN64","ZZ","QQ","RR64","RR32","IntLiteral","FloatLiteral","Float","Int","Long","BigNum","UnsignedInt","UnsignedLong","Ratio","Number","AnyIntegral"}
def rows(p):
