        q = l.rstrip("\n").split("\t")
        if len(q) >= 4: yield q
def enclosing_type(fn, ln):
    x = lines(fn)
    if not x: return None
    ls = x[1]
    for j in chain(fn, ln):
        m = re.match(r"\s*(?:value\s+)?(?:object|trait)\s+(\w+)", ls[j-1])
        if m: return m.group(1)
    return None
def tag(loc):
    b = set(); nt = False
    for x in loc.split(","):
